package com.payflow.transaction; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; @Entity @Table(name="transaction_records") public class TransactionRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(unique=true) public String transactionId; public Long senderAccountId; public Long merchantId; public BigDecimal amount; public String status; public Instant createdAt; }
